def db_clean_split():
    """Разово вычищает фразу 50/50 из описаний машин, стоящих в Грузии."""
    db = os.path.join(BASE, "crm.db")
    if not os.path.exists(db):
        return
    try:
        con = sqlite3.connect(db)
        cur = con.cursor()
        cols = [r[1] for r in cur.execute("PRAGMA table_info(cars)").fetchall()]
        if "condition_text" not in cols:
            con.close()
            return

        keys = ["rowid", "condition_text"]
        for extra in ("status", "stage"):
            if extra in cols:
                keys.append(extra)
        rows = cur.execute("SELECT %s FROM cars" % ", ".join(keys)).fetchall()

        changed = []
        for row in rows:
            data = dict(zip(keys, row))
            text = data.get("condition_text") or ""
            if "50" not in text:
                continue
            status = str(data.get("status") or "")
            stage = data.get("stage")
            in_georgia = ("Грузи" in status) or (
                isinstance(stage, int) and stage >= 3
            )
            if not in_georgia:
                continue
            new = SPLIT_RE.sub("", text)
            new = re.sub(r"\n{3,}", "\n\n", new).strip()
            if new != text:
                changed.append((new, data["rowid"]))

        if changed:
            shutil.copy2(db, db + ".bak_split")
            cur.executemany(
                "UPDATE cars SET condition_text = ? WHERE rowid = ?", changed
            )
            con.commit()
            log.info("описание почищено от 50/50 у карточек: %d", len(changed))
        con.close()
    except Exception as e:
        log.warning("чистка базы не удалась: %r", e)

