def pochinit_imena():
    """Айфон подставляет пробел вместо подчёркивания — чиним сами."""
    nado_restart = []
    try:
        files = os.listdir(BASE)
    except Exception:
        return nado_restart

    for name in files:
        if " " not in name or not name.endswith(".py"):
            continue
        pravilno = name.replace(" ", "_")
        src = os.path.join(BASE, name)
        dst = os.path.join(BASE, pravilno)
        try:
            if not os.path.exists(dst):
                shutil.move(src, dst)
                log.info("имя исправлено: «%s» -> %s", name, pravilno)
                nado_restart.append(pravilno)
                continue
            # оба есть — оставляем свежий, старый в архив
            if os.path.getmtime(src) > os.path.getmtime(dst):
                _v_arhiv(pravilno, "заменён более свежей версией")
                shutil.move(src, dst)
                log.info("«%s» новее — стал %s", name, pravilno)
                nado_restart.append(pravilno)
            else:
                _v_arhiv(name, "дубль с пробелом, версия старая")
        except Exception as e:
            log.warning("не переименовался %s: %r", name, e)
    return nado_restart
